package codework

// Tests for plan synthesis. The authoritative pin here is
// TestBuildPlanOutputIsAParserAcceptedPlan: the generated bytes are handed to
// fanout.ParsePlan, which is the SAME function `agy pro fanout --units <file>`
// applies to a plan file (internal/fanout/cli.go:573), so "the CLI accepts it"
// is verified in-process at parser level instead of by a separate dry run (the
// --units path has none).

import (
	jsonlib "encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"runtime"
	"strings"
	"testing"

	"agypro/internal/agenttools"
	"agypro/internal/fanout"
)

// writeTeamScope / otherTeamScope are two provably disjoint bounded scopes
// (fanout's PathInScope grants neither to the other).
const (
	writeTeamScope = "internal/alpha/*.go"
	otherTeamScope = "internal/beta/*.go"
)

func spec(title, scope, seat string) UnitSpec {
	return UnitSpec{Title: title, Scope: []string{scope}, Seat: seat}
}

// providerSeat is a syntactically valid PROVIDER seat (grammar:
// fanout/seatspec.go:9) and the write seat the door uses.
const providerSeat = "zoogateway/deepseek-v4.1-flash-1017"

// planUnit is the schema EXPECTED by the parser, spelled out by hand from
// fanout.Unit's JSON tags (internal/fanout/units.go:26-34). If a tag in
// units.go ever drifts, this decode stops finding a field and the test fails.
type planUnit struct {
	ID          string   `json:"id"`
	Title       string   `json:"title"`
	Scope       []string `json:"scope"`
	Deliverable string   `json:"deliverable"`
	Seat        string   `json:"seat"`
	Body        string   `json:"body"`
	Write       bool     `json:"write"`
}

func TestBuildPlanOutputIsAParserAcceptedPlan(t *testing.T) {
	data, err := BuildPlan("add a parser", []UnitSpec{{
		Title: "parser",
		Scope: []string{writeTeamScope},
		Seat:  providerSeat,
		Body:  "Parse the input grammar.",
	}})
	if err != nil {
		t.Fatalf("BuildPlan: %v", err)
	}

	// Hand-checked schema: decode with the tags units.go documents.
	var decoded []planUnit
	if err := jsonlib.Unmarshal(data, &decoded); err != nil {
		t.Fatalf("generated plan is not the documented schema: %v", err)
	}
	if len(decoded) != 1 {
		t.Fatalf("single spec must yield a single unit, got %d", len(decoded))
	}
	u := decoded[0]
	if u.ID != "u1" {
		t.Errorf("id = %q, want %q", u.ID, "u1")
	}
	if u.Title != "parser" {
		t.Errorf("title = %q", u.Title)
	}
	if len(u.Scope) != 1 || u.Scope[0] != writeTeamScope {
		t.Errorf("scope = %v, want [%s]", u.Scope, writeTeamScope)
	}
	if strings.TrimSpace(u.Deliverable) == "" {
		t.Error("deliverable is empty; fanout.ParsePlan requires one")
	}
	if u.Seat != providerSeat {
		t.Errorf("seat = %q, want %q", u.Seat, providerSeat)
	}
	if !u.Write {
		t.Error("write = false; BuildPlan must set the per-unit write opt-in")
	}
	for _, want := range []string{contractHeading, "minimal diff", "inside your scope", "## Changed Files"} {
		if !strings.Contains(u.Body, want) {
			t.Errorf("body is missing the fixed contract line %q:\n%s", want, u.Body)
		}
	}
	if !strings.Contains(u.Body, "Parse the input grammar.") {
		t.Errorf("body lost the caller's task text:\n%s", u.Body)
	}

	// Parser-as-validator: the same bytes the CLI would read from a plan file.
	path := filepath.Join(t.TempDir(), "units.json")
	if err := os.WriteFile(path, data, 0o600); err != nil {
		t.Fatalf("write plan file: %v", err)
	}
	fromFile, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read plan file: %v", err)
	}
	units, err := fanout.ParsePlan(fromFile)
	if err != nil {
		t.Fatalf("fanout.ParsePlan refused the generated plan: %v\n%s", err, data)
	}
	if len(units) != 1 || units[0].Scope[0] != writeTeamScope || !units[0].Write {
		t.Fatalf("parsed units disagree with the emitted plan: %+v", units)
	}
	if got := fanout.UnitBody(units[0]); got != u.Body {
		t.Errorf("engine body synthesis differs from the emitted body")
	}
}

func TestBuildPlanMultiUnitIsDisjoint(t *testing.T) {
	data, err := BuildPlan("two slices", []UnitSpec{
		{Title: "alpha", Scope: []string{"internal/alpha/*.go"}, Seat: providerSeat, Body: "do alpha"},
		{Title: "beta", Scope: []string{"internal/beta/parser.go"}, Seat: "provider/model-b", Body: "do beta"},
	})
	if err != nil {
		t.Fatalf("BuildPlan: %v", err)
	}
	units, err := fanout.ParsePlan(data)
	if err != nil {
		t.Fatalf("fanout.ParsePlan refused the generated plan: %v\n%s", err, data)
	}
	if len(units) != 2 {
		t.Fatalf("want 2 units, got %d", len(units))
	}
	if units[0].ID != "u1" || units[1].ID != "u2" {
		t.Fatalf("ids are not positional: %q, %q", units[0].ID, units[1].ID)
	}
}

func TestBuildPlanRefusesOverlappingScopes(t *testing.T) {
	// The contested pair from units.go:184-205: "src/*" grants
	// "src/foo/bar.go" through the directory-prefix rule, so two seats would
	// read the same file.
	_, err := BuildPlan("overlap", []UnitSpec{
		{Title: "a", Scope: []string{"src/*"}, Seat: providerSeat},
		{Title: "b", Scope: []string{"src/foo/bar.go"}, Seat: providerSeat},
	})
	if err == nil {
		t.Fatal("BuildPlan accepted two units with overlapping scopes")
	}
	if !strings.Contains(err.Error(), "overlap") {
		t.Errorf("error does not name the overlap rule: %v", err)
	}
}

func TestBuildPlanRefusesRootWideScopes(t *testing.T) {
	for _, entry := range []string{".", "/", "./", "  ", "", "src/..", "*", "**", "?*", "*/*"} {
		t.Run("scope="+entry, func(t *testing.T) {
			_, err := BuildPlan("rootwide", []UnitSpec{{Title: "t", Scope: []string{entry}, Seat: providerSeat}})
			if err == nil {
				t.Fatalf("BuildPlan accepted the unbounded scope entry %q", entry)
			}
		})
	}
}

// TestBuildPlanRefusesNonCanonicalScope pins the FIX-A1 (S2) half of the layer-1
// mirror: a scope entry naming a path shape whose written form is not its Win32
// canonical form is refused at BuildPlan time, because such a scope bounds a name
// the write never lands on ("AGENTS.md." opens "agents.md"; "sub/nul.txt" opens a
// device). The write-time guard refuses the same shapes, so authoring the plan
// would only produce a unit that cannot write inside its own scope.
func TestBuildPlanRefusesNonCanonicalScope(t *testing.T) {
	cases := map[string]string{
		"AGENTS.md.":           "dot or a space",
		"AGENTS.md ":           "governance", // the entry itself is trimmed, so this one lands on the name rule
		"sub/AGENTS.MD.":       "dot or a space",
		"providers.json.":      "dot or a space",
		"rules./team-rules.md": "dot or a space",
		"src/nul.txt":          "DOS device",
		"NUL":                  "DOS device",
		"aux.go":               "DOS device",
		"lpt1.json":            "DOS device",
		"src/..../x.txt":       "empty name",
	}
	for entry, want := range cases {
		t.Run("refused/"+entry, func(t *testing.T) {
			_, err := BuildPlan("canon", []UnitSpec{{Title: "t", Scope: []string{entry}, Seat: providerSeat}})
			if err == nil {
				t.Fatalf("BuildPlan accepted the non-canonical scope %q", entry)
			}
			if !strings.Contains(err.Error(), want) {
				t.Errorf("error = %v, want it to mention %q", err, want)
			}
		})
	}

	// Non-vacuity: canonical, bounded, non-governed entries still author a plan,
	// including the dotted extensions a real workspace uses.
	allowed := []string{
		"src/*.go",
		"internal/auxiliary/*.go",
		"config/app.yaml.bak",
		"docs/agents-notes.md",
	}
	for _, entry := range allowed {
		t.Run("allowed/"+entry, func(t *testing.T) {
			if _, err := BuildPlan("canon-ok", []UnitSpec{{Title: "t", Scope: []string{entry}, Seat: providerSeat}}); err != nil {
				t.Fatalf("BuildPlan refused the canonical scope %q: %v", entry, err)
			}
		})
	}
}

func TestBuildPlanRefusesGovernanceScope(t *testing.T) {
	refused := []string{
		"AGENTS.md",
		"rules/AGENTS.md",
		"providers.json",
		"state.json",
		"fanout-presets.json",
		"sub/.gemini/settings.json",
		".agy-pro/state-fanout.json",
		"profiles/tools/rules/registry.json",
		"providers.json.bak",
		"integrations/integrations.json",
	}
	for _, entry := range refused {
		t.Run("refused/"+entry, func(t *testing.T) {
			_, err := BuildPlan("gov", []UnitSpec{{Title: "t", Scope: []string{entry}, Seat: providerSeat}})
			if err == nil {
				t.Fatalf("BuildPlan accepted the governance scope %q", entry)
			}
			if !strings.Contains(err.Error(), "governance") {
				t.Errorf("error does not name the governance rule: %v", err)
			}
		})
	}

	// Look-alikes the guard itself keeps writable (guard.go:121-127 and the
	// doc-suffix carve-out at guard.go:111-119). A mirror that refused these
	// would be stricter than the engine and would make documentation work
	// unauthorable.
	allowed := []string{
		"docs/agents-notes.md",
		"docs/providers.json.md",
		"profiles/settings-notes.txt",
		"internal/codework/plan.go",
	}
	for _, entry := range allowed {
		t.Run("allowed/"+entry, func(t *testing.T) {
			if _, err := BuildPlan("lookalike", []UnitSpec{{Title: "t", Scope: []string{entry}, Seat: providerSeat}}); err != nil {
				t.Fatalf("BuildPlan refused the writable look-alike scope %q: %v", entry, err)
			}
		})
	}
}

func TestBuildPlanRefusesBadSeats(t *testing.T) {
	cases := []struct{ name, seat, want string }{
		{"native", "native:gemini-3.8-flash-high", "native seat"},
		{"native-uppercase", "NATIVE:claude-opus-5-5-high", "native seat"},
		{"empty", "", "missing seat"},
		{"blank", "   ", "missing seat"},
		{"two-seats", "provider/model-a,provider/model-b", "exactly one provider seat"},
		{"bad-native-id", "native:bad/id", "not a valid seat spec"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := BuildPlan("seats", []UnitSpec{{Title: "t", Scope: []string{writeTeamScope}, Seat: tc.seat}})
			if err == nil {
				t.Fatalf("BuildPlan accepted the seat %q", tc.seat)
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Errorf("error = %v, want it to mention %q", err, tc.want)
			}
			if !strings.Contains(err.Error(), "provider") {
				t.Errorf("error does not state the provider-only rule: %v", err)
			}
		})
	}
}

func TestBuildPlanRefusesMissingInputs(t *testing.T) {
	if _, err := BuildPlan("nothing", nil); err == nil {
		t.Fatal("BuildPlan accepted an empty spec slice")
	}
	_, err := BuildPlan("no scope", []UnitSpec{{Title: "t", Seat: providerSeat}})
	if err == nil || !strings.Contains(err.Error(), "missing scope") {
		t.Fatalf("BuildPlan did not refuse a unit with no scope: %v", err)
	}
	// Two specs and no titles: there is no honest fallback title.
	if _, err := BuildPlan("one goal", []UnitSpec{
		{Scope: []string{writeTeamScope}, Seat: providerSeat},
		{Scope: []string{otherTeamScope}, Seat: providerSeat},
	}); err == nil {
		t.Fatal("BuildPlan invented titles for a multi-unit plan")
	}
}

func TestBuildPlanSingleUnitTitleFallsBackToRequest(t *testing.T) {
	data, err := BuildPlan("Add a deterministic units plan builder\nsecond line", []UnitSpec{
		{Scope: []string{writeTeamScope}, Seat: providerSeat},
	})
	if err != nil {
		t.Fatalf("BuildPlan: %v", err)
	}
	units, err := fanout.ParsePlan(data)
	if err != nil {
		t.Fatalf("fanout.ParsePlan: %v", err)
	}
	if units[0].Title != "Add a deterministic units plan builder" {
		t.Fatalf("title = %q, want the first request line", units[0].Title)
	}
}

func TestBuildPlanIsDeterministic(t *testing.T) {
	specs := []UnitSpec{
		{Title: "alpha", Scope: []string{"internal/alpha/*.go", "internal/alpha/sub/b.go"}, Seat: providerSeat, Body: "alpha body"},
		{Title: "beta", Scope: []string{otherTeamScope}, Seat: "provider/model-b"},
	}
	first, err := BuildPlan("goal", specs)
	if err != nil {
		t.Fatalf("BuildPlan: %v", err)
	}
	for i := 0; i < 5; i++ {
		again, err := BuildPlan("goal", specs)
		if err != nil {
			t.Fatalf("BuildPlan: %v", err)
		}
		if string(again) != string(first) {
			t.Fatalf("BuildPlan is not deterministic (run %d differs)", i+2)
		}
	}
}

func TestBuildPlanMasksKeyShapedScopeEntry(t *testing.T) {
	const secret = "sk-live0123456789abcdefghij"
	_, err := BuildPlan("gov", []UnitSpec{{Title: "t", Scope: []string{secret + "/rules/AGENTS.md"}, Seat: providerSeat}})
	if err == nil {
		t.Fatal("BuildPlan accepted a governance path")
	}
	if strings.Contains(err.Error(), secret) {
		t.Fatalf("error leaks the key-shaped scope entry raw: %v", err)
	}
	if !strings.Contains(err.Error(), "[REDACTED]") && !strings.Contains(err.Error(), "****") {
		t.Fatalf("error carries no mask marker: %v", err)
	}
}

func TestBuildRepairPlanAnnotatesOnlyFailedUnits(t *testing.T) {
	orig, err := BuildPlan("goal", []UnitSpec{
		{Title: "alpha", Scope: []string{writeTeamScope}, Seat: providerSeat, Body: "alpha task"},
		{Title: "beta", Scope: []string{otherTeamScope}, Seat: providerSeat, Body: "beta task"},
	})
	if err != nil {
		t.Fatalf("BuildPlan: %v", err)
	}

	const secret = "Bearer abcdefghijklmnopqrst"
	tail := strings.Repeat("[build] ^^^\n", 500) + "assembly failed: " + secret + "\n"
	repaired, err := BuildRepairPlan(orig, []string{" u2 "}, tail)
	if err != nil {
		t.Fatalf("BuildRepairPlan: %v", err)
	}
	if len(repaired) > len(orig)+repairTailBytes+1024 {
		t.Fatalf("repair plan grew by %d bytes; the tail must be bounded to %d", len(repaired)-len(orig), repairTailBytes)
	}

	units, err := fanout.ParsePlan(repaired)
	if err != nil {
		t.Fatalf("fanout.ParsePlan refused the repair plan: %v", err)
	}
	if len(units) != 2 {
		t.Fatalf("repair plan must keep the same units, got %d", len(units))
	}
	if got := units[0].Body; strings.Contains(got, repairHeading) {
		t.Errorf("u1 was not a failed unit but carries the repair block")
	}
	if got := units[1].Body; !strings.Contains(got, repairHeading) || !strings.Contains(got, repairInstruction) {
		t.Errorf("u2 body is missing the repair block:\n%s", got)
	}
	if got := units[1].Body; strings.Contains(got, secret) {
		t.Errorf("repair body leaks the raw credential from the verify tail")
	}
	if got := units[1].Body; !strings.Contains(got, "[REDACTED]") {
		t.Errorf("repair body carries no redaction marker:\n%s", got)
	}
	if got := units[1].Body; !strings.Contains(got, "bytes omitted") {
		t.Errorf("repair body did not announce the bounded excerpt:\n%s", got)
	}
	// The excerpt is the TAIL: the last line of the log survives.
	if got := units[1].Body; !strings.Contains(got, "assembly failed") {
		t.Errorf("repair body dropped the end of the log:\n%s", got)
	}
}

func TestBuildRepairPlanRefusesBadInput(t *testing.T) {
	orig, err := BuildPlan("goal", []UnitSpec{{Title: "alpha", Scope: []string{writeTeamScope}, Seat: providerSeat}})
	if err != nil {
		t.Fatalf("BuildPlan: %v", err)
	}
	if _, err := BuildRepairPlan([]byte("not json"), []string{"u1"}, "tail"); err == nil {
		t.Error("BuildRepairPlan accepted a non-plan document")
	}
	if _, err := BuildRepairPlan(orig, nil, "tail"); err == nil {
		t.Error("BuildRepairPlan accepted an empty failed-unit list")
	}
	if _, err := BuildRepairPlan(orig, []string{"  "}, "tail"); err == nil {
		t.Error("BuildRepairPlan accepted a blank failed-unit list")
	}
	if _, err := BuildRepairPlan(orig, []string{"u9"}, "tail"); err == nil {
		t.Error("BuildRepairPlan accepted an id that is not in the plan")
	}
	if _, err := BuildRepairPlan([]byte("[]"), []string{"u1"}, "tail"); err == nil {
		t.Error("BuildRepairPlan accepted a plan with no units")
	}
}

// TestGovernanceScopeSetMatchesGuard pins the layer-1 mirror against its
// authority by reading internal/agenttools/guard.go and comparing the two sets
// in BOTH directions: an entry added to or removed from the guard fails here
// until codework's copy is updated. Same for the sibling prefix and the
// doc-suffix carve-out, so a widened carve-out cannot silently make a registry
// alias authorable.
func TestGovernanceScopeSetMatchesGuard(t *testing.T) {
	path := filepath.Join("..", "agenttools", "guard.go")
	src, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read authority %s: %v", path, err)
	}
	text := string(src)

	guardNames := literalKeys(t, text, "governanceWriteNames")
	assertSameSet(t, "governanceWriteNames", guardNames, governanceScopeNames)

	guardDocs := literalKeys(t, text, "governanceDocSuffixes")
	assertSameSet(t, "governanceDocSuffixes", guardDocs, governanceDocSuffixes)

	// FIX-A1 (S2): the canonicalization semantics are mirrored too, so a widened
	// or narrowed strip set / device set in the guard cannot leave the plan layer
	// refusing a different shape than the write layer.
	guardDevices := literalKeys(t, text, "reservedDeviceNames")
	assertSameSet(t, "reservedDeviceNames", guardDevices, reservedDeviceNames)

	guardTrimRe := regexp.MustCompile(`canonicalTrimSet\s*=\s*"([^"]*)"`)
	m := guardTrimRe.FindStringSubmatch(text)
	if m == nil {
		t.Fatalf("guard.go no longer declares canonicalTrimSet; update this pin")
	}
	if m[1] != canonicalTrimSet {
		t.Fatalf("canonicalTrimSet drift: guard=%q codework=%q", m[1], canonicalTrimSet)
	}

	guardPrefixRe := regexp.MustCompile(`governanceSiblingPrefix\s*=\s*"([^"]+)"`)
	m = guardPrefixRe.FindStringSubmatch(text)
	if m == nil {
		t.Fatalf("guard.go no longer declares governanceSiblingPrefix; update this pin")
	}
	if m[1] != governanceSiblingPrefix {
		t.Fatalf("governanceSiblingPrefix drift: guard=%q codework=%q", m[1], governanceSiblingPrefix)
	}
}

// literalKeys extracts the `"key": true` keys of the map literal named
// identifier from Go source text.
func literalKeys(t *testing.T, text, identifier string) map[string]bool {
	t.Helper()
	marker := identifier + " = map[string]bool{"
	idx := strings.Index(text, marker)
	if idx < 0 {
		t.Fatalf("%s map literal not found in the authority source (renamed? update this pin)", identifier)
	}
	rest := text[idx+len(marker):]
	lines := strings.Split(rest, "\n")
	var body strings.Builder
	for _, line := range lines {
		if strings.HasPrefix(strings.TrimSpace(line), "}") {
			break
		}
		body.WriteString(line)
		body.WriteString("\n")
	}
	keyRe := regexp.MustCompile(`"([^"]+)"\s*:\s*true`)
	keys := map[string]bool{}
	for _, m := range keyRe.FindAllStringSubmatch(body.String(), -1) {
		keys[m[1]] = true
	}
	if len(keys) == 0 {
		t.Fatalf("%s parsed as an empty set", identifier)
	}
	return keys
}

func assertSameSet(t *testing.T, name string, authority, mirror map[string]bool) {
	t.Helper()
	for k := range authority {
		if !mirror[k] {
			t.Errorf("%s: %q is in the guard but missing from the codework mirror", name, k)
		}
	}
	for k := range mirror {
		if !authority[k] {
			t.Errorf("%s: %q is in the codework mirror but not in the guard (mirror must not be wider)", name, k)
		}
	}
}

// TestBuildPlanRefusesNameClassShapes pins the FIX-D1a (R3-1 / R3-2 / R3-3)
// half of the layer-1 mirror: a scope entry carrying a name the write guard would
// refuse is refused at BuildPlan time, because a plan scoping a spelling the
// write never lands on can never be honored by its own unit.
//
// The three arms, all mirrored from internal/agenttools/guard.go:
//
//   - the fold: a homoglyph spelling of a governance name ("ſtate.json") is the
//     same governed target the write guard refuses;
//   - the stream separator: on Windows "AGENTS.md:evil" names a stream of
//     AGENTS.md, so no scope can bound it;
//   - the 8.3 shape on ANY component: "PROVID~1/newdir/x.md" would make the seat
//     create newdir THROUGH the alias.
func TestBuildPlanRefusesNameClassShapes(t *testing.T) {
	cases := map[string]string{
		// fold (R3-1)
		"ſtate.json":        "governance",
		"sub/ſTATE.JSON":    "governance",
		"provıders.json":    "governance",
		"agents.md":         "governance", // control in the folded class
		"ſettings.json":     "governance",
		"state-fanout.json": "governance",
	}
	if runtimeNameRules {
		// stream syntax (R3-2)
		cases["AGENTS.md:evil"] = "alternate-data-stream"
		cases["src/notes.md:stream"] = "alternate-data-stream"
		cases["providers.json::$DATA"] = "alternate-data-stream"
		// 8.3 shape on every component (R3-3)
		cases["PROVID~1/newdir/x.md"] = "8.3"
		cases["sub/NEWDIR~2/x.md"] = "8.3"
		cases["notes~1.md"] = "8.3"
	}
	for entry, want := range cases {
		t.Run("refused/"+entry, func(t *testing.T) {
			_, err := BuildPlan("d1a", []UnitSpec{{Title: "t", Scope: []string{entry}, Seat: providerSeat}})
			if err == nil {
				t.Fatalf("BuildPlan accepted the scope %q", entry)
			}
			if !strings.Contains(err.Error(), want) {
				t.Errorf("error = %v, want it to mention %q", err, want)
			}
		})
	}

	// Non-vacuity: ordinary names, unicode names and non-alias "~"-free paths
	// still author a plan.
	allowed := []string{
		"src/*.go",
		"café.json",
		"docs/naïve-notes.md",
		"reports/code/261024_0001/summary.json",
	}
	for _, entry := range allowed {
		t.Run("allowed/"+entry, func(t *testing.T) {
			if _, err := BuildPlan("d1a-ok", []UnitSpec{{Title: "t", Scope: []string{entry}, Seat: providerSeat}}); err != nil {
				t.Fatalf("BuildPlan refused the benign scope %q: %v", entry, err)
			}
		})
	}
}

// TestNameClassMirrorMatchesGuard pins the three FIX-D1a mirrors against the
// guard BEHAVIOURALLY (not just by reading the authority's source): the fold, the
// stream gate and the 8.3 shape table are compared call-for-call over a table
// that includes the homoglyph, the separator and the alias shapes.
//
// FIX-E2 made the fold a DELEGATION (win32FoldName calls agenttools.Win32NameFold,
// so there is one implementation and no copy to drift), which means the loop below
// is an identity check on this tree. It stays for two reasons: it is the pin that
// fails the moment someone re-introduces a local copy that drifts on ſ/ı/K, and it
// documents which names the fold is expected to merge (ſtate.json -> state.json)
// next to the governance sets that depend on it.
func TestNameClassMirrorMatchesGuard(t *testing.T) {
	foldTable := []string{
		"state.json", "STATE.JSON", "ſtate.json", "ſTATE.JSON", "provıders.json",
		"K.txt", "café.json", "CAFÉ.JSON", "ＡＧＥＮＴＳ.ＭＤ", "com¹", "ß", "日本語.md",
	}
	for _, name := range foldTable {
		if got, want := win32FoldName(name), agenttools.Win32NameFold(name); got != want {
			t.Errorf("fold drift on %q: codework=%q guard=%q", name, got, want)
		}
	}

	shapeTable := []string{
		"PROVID~1.JSON", "provid~12", "file~1.tar.gz", "a~1", "a~12345",
		"providers.json", "notes.md", "~1.JSON", "a~b.JSON", "report~20261024", "a~123456",
	}
	for _, comp := range shapeTable {
		// Compare what each layer ENFORCES: codework gates the arm with
		// runtimeNameRules (this package has no build-tagged file) and the guard
		// gates it with a build-tagged stub, so the raw functions differ on a
		// host without 8.3 names by design.
		planEnforces := runtimeNameRules && win32ShortAliasShape(comp)
		guardEnforces := agenttools.Win32ShortAliasShape(comp)
		if planEnforces != guardEnforces {
			t.Errorf("8.3 shape drift on %q: codework enforces=%v guard enforces=%v", comp, planEnforces, guardEnforces)
		}
	}

	// Stream separator: the two layers must agree on the governed verdict for a
	// stream-suffixed name (the guard refuses the component, the plan refuses the
	// scope entry), and neither may refuse the stream-free control.
	for _, name := range []string{"AGENTS.md:evil", "AGENTS.md::$DATA", "state.json:1", "notes-2026.md"} {
		_, _, planRefuse := governanceScopeRefusal(name)
		_, guardRefuse := agenttools.GovernanceWriteRefusal(name)
		if planRefuse != guardRefuse {
			t.Errorf("stream verdict drift on %q: plan refuses=%v guard refuses=%v", name, planRefuse, guardRefuse)
		}
	}

	// Gate parity: both layers must switch the host-side rules on the same
	// property. The guard declares it as a build-tagged const, so this pin reads
	// both platform files and checks codework's runtime expression carries the
	// same condition.
	winSrc, err := os.ReadFile(filepath.Join("..", "agenttools", "guard_win32_windows.go"))
	if err != nil {
		t.Fatalf("read guard windows arm: %v", err)
	}
	otherSrc, err := os.ReadFile(filepath.Join("..", "agenttools", "guard_win32_other.go"))
	if err != nil {
		t.Fatalf("read guard non-windows arm: %v", err)
	}
	if !strings.Contains(string(winSrc), "win32StreamSyntaxRule = true") {
		t.Error("guard_win32_windows.go no longer declares win32StreamSyntaxRule = true; update this pin")
	}
	if !strings.Contains(string(otherSrc), "win32StreamSyntaxRule = false") {
		t.Error("guard_win32_other.go no longer declares win32StreamSyntaxRule = false; update this pin")
	}
	planSrc, err := os.ReadFile("plan.go")
	if err != nil {
		t.Fatalf("read plan.go: %v", err)
	}
	if !strings.Contains(string(planSrc), `runtimeNameRules = runtime.GOOS == "windows"`) {
		t.Error("plan.go no longer declares runtimeNameRules = runtime.GOOS == \"windows\"; update this pin")
	}
	if runtimeNameRules != (runtime.GOOS == "windows") {
		t.Errorf("runtimeNameRules = %v on %s", runtimeNameRules, runtime.GOOS)
	}
}
